passes.shader:
let wind = clamp(frame.params.y * 0.014, 0.04, 0.8);
let t = frame.info.z * wind;
let p = vec2<f32>(uv.x * 1.3, uv.y);
let a = sin(p.x * 3.8 + p.y * 2.1 + t * 0.42);
let b = cos(p.y * 6.4 - p.x * 2.6 - t * 0.33 + a);
let pressure = 0.5 + 0.22 * a + 0.15 * b + 0.085 * sin(p.x * 7.0 - p.y * 4.8 + b);
let warm = clamp((frame.params.x + 12.0) / 48.0, 0.0, 1.0);
return vec4<f32>(pressure, warm, 0.5 + 0.5 * a, 1.0);

let sample_data = textureSample(input0, linear_sampler, uv);
let field = sample_data.r * frame.params.x;
let d = abs(fract(field + 0.5) - 0.5);
let line = 1.0 - smoothstep(0.015, max(0.045, fwidth(field) * 1.2), d);
let rim = 1.0 - smoothstep(0.04, 0.24, d);
let paper = mix(vec3<f32>(0.018, 0.085, 0.14), vec3<f32>(0.055, 0.24, 0.28), sample_data.b);
let ink = mix(vec3<f32>(0.32, 0.83, 0.85), vec3<f32>(0.99, 0.73, 0.35), sample_data.g);
let dots = smoothstep(0.93, 0.99, cos(position.x * 0.75) * cos(position.y * 0.75));
return vec4<f32>(paper + ink * (0.72 * line + 0.095 * rim) + dots * 0.035, 1.0);
